using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "OnMouseOverRandomTargetAction", menuName = "Data/Battle/Actions/OnMouseOverRandomTargetAction")]
public class OnMouseOverRandomTargetAction : OnMouseOverNoTargetSelectionAction
{
	protected override void OnMouseOver()
	{
		base.OnMouseOver();
		for (int i = 0; i < actionHighlightTargets.Count; i++)
		{
			actionHighlightTargets[i].GetComponentInChildren<DicePlacement>().ToggleQuestionMark(toggle: true);
		}
	}

	protected override void OnMouseExit()
	{
		base.OnMouseExit();
		for (int i = 0; i < actionHighlightTargets.Count; i++)
		{
			actionHighlightTargets[i].GetComponentInChildren<DicePlacement>().ToggleQuestionMark(toggle: false);
		}
	}
}
